75b68e2dd22","lessonTitle":"أراجع الحروف (4)","sourcePage":10,"activity_order":3,"activity_type":"multiple_choice","title":"أميز الصاد","section":"practice","prompt":"أي كلمة تبدأ بحرف الصاد؟","content":{"origin":"DADYOOM_BH_G2_7_ORIGINAL_LISTENING_PHONICS_35_20261030","originalReference":"أراجع اليوم أربعة حروف متقاربة في الشكل أو النطق: «ص، ض، ط، ظ». ألاحظ أن «ض» تشبه «ص» في الرسم مع نقطة فوق الضاد، وأن «ظ» تشبه «ط» مع نقطة فوق الظاء. أقرأ كلمات «صبر، ضوء، طائر، ظرف» مع المعلم، ثم ألاحظ الحرف الأول في كل كلمة. هذه أمثلة تأليفية تكميلية لضاديوم وليست نص ورقة الوزارة.","options":["صبر","طائر","ضوء"],"grade":2,"sourceKind":"original grade2 supplementary phonics comparison"},"answer":{"correct":"صبر"}},{"lessonId":"c9b512d5-6f6a-419b-a5ec-f75b68e2dd22","lessonTitle":"أراجع الحروف (4)","sourcePage":10,"activity_order":4,"activity_type":"multiple_choice","title":"أميز الطاء","section":"practice","prompt":"أي كلمة تبدأ بحرف الطاء؟","content":{"origin":"DADYOOM_BH_G2_7_ORIGINAL_LISTENING_PHONICS_35_20261030","originalReference":"أراجع اليوم أربعة حروف متقاربة في الشكل أو النطق: «ص، ض، ط، ظ». ألاحظ أن «ض» تشبه «ص» في الرسم مع نقطة فوق الضاد، وأن «ظ» تشبه «ط» مع نقطة فوق الظاء. أقرأ كلمات «صبر، ضوء، طائر، ظرف» مع المعلم، ثم ألاحظ الحرف الأول في كل كلمة. هذه أمثلة تأليفية تكميلية لضاديوم وليست نص ورقة الوزارة.","options":["ظرف","ضوء","طائر"],"grade":2,"sourceKind":"original grade2 supplementary phonics comparison"},"answer":{"correct":"طائر"}},{"lessonId":"c9b512d5-6f6a-419b-a5ec-f75b68e2dd22","lessonTitle":"أراجع الحروف (4)","sourcePage":10,"activity_order":5,"activity_type":"multiple_choice","title":"أميز الظاء","section":"practice","prompt":"أي كلمة تبدأ بحرف الظاء؟","content":{"origin":"DADYOOM_BH_G2_7_ORIGINAL_LISTENING_PHONICS_35_20261030","originalReference":"أراجع اليوم أربعة حروف متقاربة في الشكل أو النطق: «ص، ض، ط، ظ». ألاحظ أن «ض» تشبه «ص» في الرسم مع نقطة فوق الضاد، وأن «ظ» تشبه «ط» مع نقطة فوق الظاء. أقرأ كلمات «صبر، ضوء، طائر، ظرف» مع المعلم، ثم ألاحظ الحرف الأول في كل كلمة. هذه أمثلة تأليفية تكميلية لضاديوم وليست نص ورقة الوزارة.","options":["ظرف","صبر","طائر"],"grade":2,"sourceKind":"original grade2 supplementary phonics comparison"},"answer":{"correct":"ظرف"}},{"lessonId":"c9b512d5-6f6a-419b-a5ec-f75b68e2dd22","lessonTitle":"أراجع الحروف (4)","sourcePage":10,"activity_order":6,"activity_type":"multiple_choice","title":"أتتبع موضع النقطة","section":"practice","prompt":"أي حرف يشبه الطاء وتوجد فوقه نقطة؟","content":{"origin":"DADYOOM_BH_G2_7_ORIGINAL_LISTENING_PHONICS_35_20261030","originalReference":"أراجع اليوم أربعة حروف متقاربة في الشكل أو النطق: «ص، ض، ط، ظ». ألاحظ أن «ض» تشبه «ص» في الرسم مع نقطة فوق الضاد، وأن «ظ» تشبه «ط» مع نقطة فوق الظاء. أقرأ كلمات «صبر، ضوء، طائر، ظرف» مع المعلم، ثم ألاحظ الحرف الأول في كل كلمة. هذه أمثلة تأليفية تكميلية لضاديوم وليست نص ورقة الوزارة.","options":["ط","ظ","ص"],"grade":2,"sourceKind":"original grade2 supplementary phonics comparison"},"answer":{"correct":"ظ"}}]$g2listen$::jsonb)
AS t("lessonId" text,"lessonTitle" text,"sourcePage" int,activity_order int,activity_type text,title text,section text,prompt text,content jsonb,answer jsonb);
DO $safe$
DECLARE eligible integer; inserted integer; history integer;
BEGIN
 IF (SELECT count(*) FROM pg_temp.dadyoom_bh_g2_35_original)<>35
 OR (SELECT count(DISTINCT lesson_id) FROM pg_temp.dadyoom_bh_g2_35_original)<>7
 OR (SELECT count(DISTINCT (lesson_id,activity_order)) FROM pg_temp.dadyoom_bh_g2_35_original)<>35
 OR EXISTS (SELECT 1 FROM pg_temp.dadyoom_bh_g2_35_original t WHERE
 t.activity_order NOT BETWEEN 2 AND 6 OR length(t.prompt)<15 OR t.content ? 'answer' OR t.content ? 'correct'
 OR t.answer IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(t.content->'options') a WHERE a=t.answer->>'correct')
 OR (t.activity_type='listening' AND (t.content->>'requiresTeacherRead')<>'true')
 OR (t.activity_type='listening' AND length(t.content->>'text')<135)
 OR (t.activity_type='multiple_choice' AND length(t.content->>'originalReference')<160))
 THEN RAISE EXCEPTION 'Invalid 35 activity content or leaking a private answer'; END IF;
 WITH targets AS (
 SELECT l.id,l.title,l.source_page_start,co.code country,g.grade_number grade,l.status,l.source_pdf_url,l.content,
 (SELECT count(*) FROM public.lesson_activities a WHERE a.lesson_id=l.id AND a.is_published) n,
 (SELECT max(activity_order) FROM public.lesson_activities a WHERE a.lesson_id=l.id) mx,
 EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 OR EXISTS(SELECT 1 FROM public.lesson_activity_attempts t JOIN public.lesson_activities a ON a.id=t.activity_id WHERE a.lesson_id=l.id)
 OR EXISTS(SELECT 1 FROM public.question_attempts t JOIN public.questions q ON q.id=t.question_id WHERE q.lesson_id=l.id) has_history
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 WHERE co.code='BH' AND g.grade_number=2 AND l.status='published'
 )
 SELECT count(DISTINCT t.id) INTO eligible FROM targets t JOIN pg_temp.dadyoom_bh_g2_35_original s ON s.lesson_id=t.id AND s.lesson_title=t.title AND s.source_page=t.source_page_start
 WHERE t.n=1 AND t.mx=1 AND NOT t.has_history AND t.source_pdf_url IS NOT NULL
 AND t.content LIKE '%ضاديوم%';
 IF eligible<>7 THEN RAISE EXCEPTION 'Expected 7 untouched Grade2 Bahrain lessons, got %',eligible; END IF;
 IF EXISTS(SELECT 1 FROM public.lesson_activities a WHERE a.content->>'origin'='DADYOOM_BH_G2_7_ORIGINAL_LISTENING_PHONICS_35_20261030')
 THEN RAISE EXCEPTION 'Prevent duplicate 35 listening/phonics tasks'; END IF;
 INSERT INTO public.lesson_activities
 (lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
 SELECT l.id,t.title,t.activity_type,
 CASE WHEN t.activity_type='listening' THEN 'استمع إلى المقطع بصوت المعلم أولًا، ثم أجب. نص إثرائي مستقل عن الكتاب الرسمي.'
 ELSE 'اقرأ بطاقة الحروف الأصلية ثم أجب. تمرين داعم مستقل عن ورقة الوزارة.' END,
 t.content,t.activity_order,5,true,t.section,t.prompt,t.answer,false
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 JOIN pg_temp.dadyoom_bh_g2_35_original t ON t.lesson_id=l.id AND t.lesson_title=l.title AND t.source_page=l.source_page_start
 WHERE co.code='BH' AND g.grade_number=2 AND l.status='published'
 AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities a ON a.id=at.activity_id WHERE a.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>35 THEN RAISE EXCEPTION 'Atomic rollback: expected 35 grade2 activities, got %',inserted; END IF;
 RAISE NOTICE 'DADYOOM_BH_G2_ORIGINAL_STANDALONE_LISTENING_AND_PHONICS=%',inserted;
END $safe$;
COMMIT;